using System.Diagnostics;
using System.Text;
using Puck.Abstractions;

namespace Puck.Assets;

/// <summary>A content-addressed cache of generated bytes. Every read checks the payload's integrity; a missing,
/// corrupt or unreadable entry derives again. Cache storage failures never refuse the derived product.</summary>
public sealed class DerivedBytes {
    private readonly CodeClosure m_code;
    private readonly string m_name;
    private long m_hits;
    private long m_misses;

    /// <summary>Creates a cache owner with its production deriving roots.</summary>
    /// <param name="name">The diagnostic owner name.</param>
    /// <param name="roots">Assembly, full type and method roots.</param>
    public DerivedBytes(string name, IReadOnlyList<(string Assembly, string Type, string? Method)> roots) {
        m_name = name;
        m_code = CodeClosure.Of(directory: AppContext.BaseDirectory, roots: roots,
            stopTypes: new HashSet<string>(collection: [typeof(DerivedBytes).FullName!, typeof(CodeClosure).FullName!], comparer: StringComparer.Ordinal));
    }

    /// <summary>Gets bytes derived from explicit inputs and the deriving code, including applied code updates.</summary>
    /// <param name="inputs">The canonical inputs to the generator.</param>
    /// <param name="derive">The derivation of those inputs.</param>
    /// <param name="directory">An explicit cache directory, or the per-user derived cache.</param>
    /// <returns>A private byte array.</returns>
    public byte[] Get(string inputs, Func<byte[]> derive, string? directory = null) {
        var identity = ContentPin.Compute(content: Encoding.UTF8.GetBytes(s: $"{m_name}\n{m_code.Hash:x32}\n{CodeRevision.AppliedTo(reads: m_code.Reads)}\n{inputs}"));
        ContentAddressedStore? store = null;
        try {
            store = new ContentAddressedStore(root: directory ?? PuckUserDirectory.Resolve(name: "derived"), retention: new CacheBound(MaxBytes: 64L << 20, MaxEntries: 1024));
            if (store.TryResolveDerived(kind: m_name, inputHash: identity, hash: out var pin) && store.TryGet(pin: pin, content: out var entry)) {
                Console.Error.WriteLine(value: $"[derived] {m_name} {inputs}: hit; hits={Interlocked.Increment(location: ref m_hits)} misses={Interlocked.Read(location: ref m_misses)}");
                return entry;
            }
        } catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { }
        var watch = Stopwatch.StartNew();
        var bytes = derive();
        try { store?.SetDerived(kind: m_name, inputHash: identity, outputHash: store.Put(content: bytes)); }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { }
        Console.Error.WriteLine(value: $"[derived] {m_name} {inputs}: miss; hits={Interlocked.Read(location: ref m_hits)} misses={Interlocked.Increment(location: ref m_misses)} deriveMs={watch.Elapsed.TotalMilliseconds:F3}");
        return bytes;
    }
}
